const rawInput = $input.first()?.json || {};
let rawAgent1Json = rawInput.agent1_json ?? rawInput.agent_e_json ?? rawInput['Agent 1 JSON 结果'] ?? rawInput['Agent E JSON 结果'] ?? rawInput.data ?? '';
const approvedTopicsText = String(rawInput.approved_topics ?? rawInput['人工确认的选题名称或编号'] ?? '').trim();

// 支持用户从 Markdown 报告中复制 ```json 包裹的 JSON。
function stripMarkdownFence(value) {
  const text = typeof value === 'string' ? value.trim() : value;
  if (typeof text !== 'string') return text;
  return text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

function looksLikeTopic(item) {
  return !!item && typeof item === 'object' && (
    item.title !== undefined || item.topic !== undefined || item.original_topic !== undefined || item.ranking !== undefined || item.row_number !== undefined
  );
}

function arrayFromKnownKeys(value) {
  if (!value || typeof value !== 'object') return [];
  const possibleKeys = ['ranked_topics', 'top_topics', 'results', 'topics', 'recommendations', 'records'];
  for (const key of possibleKeys) {
    if (Array.isArray(value[key])) return value[key];
  }
  return [];
}

function findTopicArray(value) {
  if (Array.isArray(value)) {
    // 新 Agent E 实际输出是：[{ ranked_topics: [...] }]，这里必须取内部 ranked_topics，而不是外层数组。
    for (const item of value) {
      const nested = arrayFromKnownKeys(item);
      if (nested.length > 0) return nested;
    }
    // 兼容旧版 mock：数组本身就是 topic list。
    if (value.some(looksLikeTopic)) return value;
    return [];
  }

  const direct = arrayFromKnownKeys(value);
  if (direct.length > 0) return direct;
  if (looksLikeTopic(value)) return [value];
  return [];
}

function normalizeTopic(topic, index) {
  const title = String(topic.title ?? topic.topic ?? topic.original_topic ?? topic.name ?? '').trim();
  const topicName = String(topic.topic ?? topic.title ?? title).trim();
  const ranking = Number(topic.ranking ?? topic.rank ?? index + 1);
  return {
    ...topic,
    ranking,
    row_number: topic.row_number,
    topic: topicName || title,
    title,
    ingredient: topic.ingredient,
    angle: topic.angle,
    target_audience: topic.target_audience,
    score: topic.score ?? topic.total_score,
    recommendation: topic.recommendation,
    reason: topic.reason,
    risk_level: topic.risk_level,
    risk_alert: topic.risk_alert,
    focus_bonus: topic.focus_bonus,
    suggested_hook: topic.suggested_hook,
    source_index: index + 1,
  };
}

try {
  let parsed = rawAgent1Json;
  if (typeof parsed === 'string') parsed = JSON.parse(stripMarkdownFence(parsed));

  const topics = findTopicArray(parsed)
    .map((topic, index) => normalizeTopic(topic, index))
    .filter((topic) => topic.title || topic.topic);

  return [{
    json: {
      status: 'parsed',
      parse_error: '',
      source_agent: 'agent_e',
      approved_topics_text: approvedTopicsText,
      topics,
      total_topics: topics.length,
    }
  }];
} catch (error) {
  return [{
    json: {
      status: 'error',
      parse_error: `Agent E / Agent 1 JSON 解析失败：${error.message}`,
      source_agent: 'agent_e',
      approved_topics_text: approvedTopicsText,
      topics: [],
      total_topics: 0,
    }
  }];
}

const data = $input.first()?.json || {};

if (data.status === 'error') {
  return [{ json: { ...data, selected_topics: [], selected_count: 0 } }];
}

const approvedText = String(data.approved_topics_text || '').trim();
const topics = Array.isArray(data.topics) ? data.topics : [];

function normalizeText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
}
function compactText(value) {
  return normalizeText(value).replace(/\s+/g, '');
}
function parseApprovedTokens(text) {
  return text.split(/[\n,，;；]+/).map((item) => item.trim()).filter(Boolean);
}
function tokenMatchesTopic(token, topic) {
  const normalizedToken = normalizeText(token);
  const compactToken = compactText(token);
  const title = normalizeText(topic.title);
  const topicName = normalizeText(topic.topic);
  const compactTitle = compactText(topic.title);
  const compactTopic = compactText(topic.topic);
  const ranking = String(topic.ranking ?? topic.rank ?? topic.source_index ?? '');
  const rowNumber = String(topic.row_number ?? '');

  return ranking === normalizedToken
    || rowNumber === normalizedToken
    || (!!compactToken && compactTitle.includes(compactToken))
    || (!!compactTitle && compactToken.includes(compactTitle))
    || (!!compactToken && compactTopic.includes(compactToken))
    || (!!compactTopic && compactToken.includes(compactTopic))
    || (!!normalizedToken && title.includes(normalizedToken))
    || (!!normalizedToken && topicName.includes(normalizedToken));
}
function isYes(value) {
  return ['yes', 'true', 'recommended', '制作', '推荐制作'].includes(normalizeText(value));
}
function isLowRisk(value) {
  return ['low', '低', '低风险'].includes(normalizeText(value));
}

let selectedTopics = [];

if (approvedText) {
  const tokens = parseApprovedTokens(approvedText);
  selectedTopics = topics.filter((topic) => tokens.some((token) => tokenMatchesTopic(token, topic)));
} else {
  selectedTopics = topics.filter((topic) => {
    const recommended = topic.recommendation ?? topic.is_recommended_for_production ?? topic.recommended;
    const grade = String(topic.recommendation_grade ?? topic.grade ?? '').trim().toUpperCase();
    const riskLevel = topic.risk_level ?? topic.riskLevel ?? '';

    const agentEPass = isYes(recommended) && isLowRisk(riskLevel);
    const legacyPass = isYes(recommended) && ['A', 'B'].includes(grade);
    const simplePass = topic.recommended === true || topic.is_recommended_for_production === true;
    return agentEPass || legacyPass || simplePass;
  }).slice(0, 5);
}

const limitedTopics = selectedTopics.slice(0, 5);
const status = limitedTopics.length > 0 ? 'selected' : 'insufficient_data';

return [{
  json: {
    ...data,
    status,
    selected_topics: limitedTopics,
    selected_count: limitedTopics.length,
    selection_note: limitedTopics.length > 0
      ? '已选择人工确认或默认合格选题。'
      : '没有找到合格选题：请填写人工确认选题名称/编号，或提供 recommendation = Yes 且 risk_level = Low 的 Agent E 选题。',
  }
}];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{
    json: {
      ...data,
      risk_checked_topics: [],
    }
  }];
}

const blockedPatterns = [
  { phrase: 'cure', reason: '可能暗示治愈疾病。' },
  { phrase: 'treat', reason: '可能暗示治疗疾病。' },
  { phrase: 'prevent', reason: '可能暗示预防疾病。' },
  { phrase: 'reverse', reason: '可能暗示逆转疾病或身体状态。' },
  { phrase: 'heal', reason: '可能暗示修复或治愈。' },
  { phrase: 'guaranteed', reason: '保证结果属于高风险绝对化表达。' },
  { phrase: 'replace medication', reason: '不能暗示替代药物。' },
  { phrase: 'stop medication', reason: '不能暗示停止服药。' },
  { phrase: '治愈', reason: '可能暗示治愈疾病。' },
  { phrase: '治疗', reason: '可能暗示治疗疾病。' },
  { phrase: '预防疾病', reason: '可能暗示疾病预防。' },
  { phrase: '逆转', reason: '可能暗示逆转疾病或身体状态。' },
  { phrase: '根治', reason: '可能暗示根治疾病。' },
  { phrase: '保证有效', reason: '保证结果属于高风险绝对化表达。' },
  { phrase: '替代药物', reason: '不能暗示替代药物。' },
  { phrase: '停止服药', reason: '不能暗示停止服药。' },
];

const highPatterns = [
  { phrase: 'eliminate', reason: '可能暗示完全消除健康问题。' },
  { phrase: 'miracle', reason: '奇迹式效果属于高风险营销表达。' },
  { phrase: 'detox', reason: '排毒表述容易被理解为生理功效声明。' },
  { phrase: 'burn fat', reason: '燃脂属于强生理效果声明。' },
  { phrase: 'rapid weight loss', reason: '快速减重属于高风险效果声明。' },
  { phrase: 'lower blood sugar', reason: '降血糖涉及疾病相关生理指标。' },
  { phrase: 'clinically proven', reason: '临床证明需要可靠依据，默认需要人工复核。' },
  { phrase: '神奇疗效', reason: '神奇疗效属于高风险营销表达。' },
  { phrase: '排毒', reason: '排毒表述容易被理解为生理功效声明。' },
  { phrase: '快速减肥', reason: '快速减肥属于高风险效果声明。' },
  { phrase: '降血糖', reason: '降血糖涉及疾病相关生理指标。' },
];

const mediumPatterns = [
  { phrase: 'diabetes', reason: '涉及具体疾病人群，需要谨慎。' },
  { phrase: 'blood pressure', reason: '涉及生理指标，需要谨慎。' },
  { phrase: 'inflammation', reason: '炎症相关表达可能被理解为医疗声明。' },
  { phrase: 'pain relief', reason: '止痛/缓解疼痛可能被理解为治疗声明。' },
  { phrase: '疾病', reason: '涉及疾病，需要谨慎。' },
  { phrase: '血压', reason: '涉及生理指标，需要谨慎。' },
  { phrase: '炎症', reason: '炎症相关表达可能被理解为医疗声明。' },
  { phrase: '止痛', reason: '止痛可能被理解为治疗声明。' },
];

function includesPhrase(text, phrase) {
  const lowerText = text.toLowerCase();
  const lowerPhrase = phrase.toLowerCase();
  if (/^[a-z0-9 ]+$/.test(lowerPhrase)) {
    const escaped = lowerPhrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
    return new RegExp(`\\b${escaped}\\b`, 'i').test(lowerText);
  }
  return lowerText.includes(lowerPhrase);
}

function inspectTopic(topic) {
  const combinedText = [
    topic.title,
    topic.topic,
    topic.suggested_hook,
    topic.hook,
    topic.angle,
    topic.recommendation_reason,
    topic.risk_alerts,
  ].flat().filter(Boolean).join(' ');

  const matched = [];
  for (const item of [...blockedPatterns, ...highPatterns, ...mediumPatterns]) {
    if (includesPhrase(combinedText, item.phrase)) {
      matched.push(item);
    }
  }

  const blockedMatches = matched.filter((item) => blockedPatterns.some((pattern) => pattern.phrase === item.phrase));
  const highMatches = matched.filter((item) => highPatterns.some((pattern) => pattern.phrase === item.phrase));
  const mediumMatches = matched.filter((item) => mediumPatterns.some((pattern) => pattern.phrase === item.phrase));

  let riskLevel = 'low';
  if (blockedMatches.length > 0) {
    riskLevel = 'blocked';
  } else if (highMatches.length > 0) {
    riskLevel = 'high';
  } else if (mediumMatches.length > 0) {
    riskLevel = 'medium';
  }

  return {
    ...topic,
    original_topic: topic.title || topic.topic,
    detected_claims: matched.map((item) => item.reason),
    flagged_phrases: matched.map((item) => item.phrase),
    risk_level: riskLevel,
    risk_reasons: matched.length > 0 ? matched.map((item) => item.reason) : ['未发现明显医疗声明词，但仍需人工确认。'],
    needs_rewrite: riskLevel !== 'low',
    compliance_note: '关键词匹配只是内容风险筛查，不构成最终医疗、法律或平台合规结论。',
  };
}

const riskCheckedTopics = (data.selected_topics || []).map(inspectTopic);

return [{
  json: {
    ...data,
    status: 'risk_checked',
    risk_checked_topics: riskCheckedTopics,
  }
}];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{
    json: {
      ...data,
      rewritten_topics: [],
    }
  }];
}

const cautiousPhrases = [
  'may support',
  'may help support',
  'is traditionally used for',
  'has been studied for',
  'some research suggests',
  'is associated with',
  'general wellness',
  'educational information only',
];

const replacements = [
  ['cures', 'is traditionally discussed for general wellness around'],
  ['cure', 'is traditionally discussed for general wellness around'],
  ['treats', 'may support general wellness related to'],
  ['treat', 'may support general wellness related to'],
  ['prevents', 'may help support a healthy routine around'],
  ['prevent', 'may help support a healthy routine around'],
  ['reverses', 'is associated with general wellness conversations about'],
  ['reverse', 'is associated with general wellness conversations about'],
  ['heals', 'may help support comfort around'],
  ['heal', 'may help support comfort around'],
  ['eliminates', 'may help support a balanced routine around'],
  ['eliminate', 'may help support a balanced routine around'],
  ['guaranteed', 'worth exploring as general wellness education'],
  ['miracle', 'traditional'],
  ['detox', 'daily reset routine'],
  ['burn fat', 'support an active lifestyle'],
  ['rapid weight loss', 'balanced wellness routine'],
  ['lower blood sugar', 'support general metabolic wellness education'],
  ['replace medication', 'support general wellness education'],
  ['stop medication', 'support general wellness education'],
  ['clinically proven', 'has been studied for'],
  ['治愈', '用于一般健康教育讨论'],
  ['治疗', '用于一般健康支持讨论'],
  ['预防疾病', '支持日常健康习惯'],
  ['逆转', '用于一般健康教育讨论'],
  ['根治', '用于一般健康教育讨论'],
  ['保证有效', '可作为健康知识了解'],
  ['神奇疗效', '传统使用背景'],
  ['排毒', '日常轻盈感习惯'],
  ['快速减肥', '平衡生活方式'],
  ['降血糖', '代谢健康教育'],
  ['替代药物', '一般健康教育'],
  ['停止服药', '一般健康教育'],
];

function replacePhrase(text) {
  let output = String(text || '').trim();
  const changed = [];
  for (const [from, to] of replacements) {
    const escaped = from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
    const regex = /^[a-z0-9 ]+$/i.test(from) ? new RegExp(`\\b${escaped}\\b`, 'gi') : new RegExp(escaped, 'g');
    if (regex.test(output)) {
      output = output.replace(regex, to);
      changed.push(from);
    }
  }
  return { output, changed };
}

function buildSafeTitle(topic) {
  const originalTitle = String(topic.title || topic.topic || '').trim();
  const replaced = replacePhrase(originalTitle);
  if (replaced.output && replaced.output !== originalTitle) {
    return replaced;
  }
  if (topic.risk_level === 'low') {
    return { output: originalTitle, changed: [] };
  }
  return {
    output: `${originalTitle}: what to know before sharing`,
    changed: topic.flagged_phrases || [],
  };
}

function buildSafeHook(topic) {
  const originalHook = String(topic.suggested_hook || topic.hook || topic.recommendation_reason || topic.title || '').trim();
  const replaced = replacePhrase(originalHook);
  if (replaced.output && replaced.output !== originalHook) {
    return replaced;
  }
  if (topic.risk_level === 'low') {
    return { output: originalHook || `A simple wellness note about ${topic.title}.`, changed: [] };
  }
  return {
    output: `Before turning this into health content, frame it as educational information only and avoid disease claims.`,
    changed: topic.flagged_phrases || [],
  };
}

function rewriteTopic(topic) {
  const titleRewrite = buildSafeTitle(topic);
  const hookRewrite = buildSafeHook(topic);
  const changedPhrases = Array.from(new Set([...(titleRewrite.changed || []), ...(hookRewrite.changed || []), ...(topic.flagged_phrases || [])]));

  let finalRiskLevel = topic.risk_level;
  if (topic.risk_level === 'high' && changedPhrases.length > 0) {
    finalRiskLevel = 'medium';
  }
  if (topic.risk_level === 'medium' && changedPhrases.length > 0) {
    finalRiskLevel = 'low';
  }

  const reviewRequired = ['blocked', 'high', 'medium'].includes(topic.risk_level);
  const readyForAgent3 = topic.risk_level === 'blocked' ? false : finalRiskLevel !== 'blocked';

  return {
    original_title: topic.title || topic.topic,
    compliant_title: titleRewrite.output,
    original_hook: topic.suggested_hook || topic.hook || '',
    compliant_hook: hookRewrite.output,
    safe_core_claim: `${cautiousPhrases[1]} general wellness education. Do not present this as medical advice, treatment, dosage guidance, or a guaranteed result.`,
    removed_or_changed_phrases: changedPhrases,
    rewrite_explanation: topic.needs_rewrite
      ? '已将高风险或绝对化健康表达改为更谨慎的教育性、传统使用或一般健康支持表达。'
      : '未发现明显高风险表达，保留原有吸引力，同时提醒发布前人工审核。',
    final_risk_level: finalRiskLevel,
    ready_for_agent3: readyForAgent3,
    review_required: reviewRequired,
    risk_check: {
      detected_claims: topic.detected_claims || [],
      flagged_phrases: topic.flagged_phrases || [],
      risk_level: topic.risk_level,
      risk_reasons: topic.risk_reasons || [],
    },
  };
}

const rewrittenTopics = (data.risk_checked_topics || []).map(rewriteTopic);

return [{
  json: {
    ...data,
    status: 'rewritten',
    rewritten_topics: rewrittenTopics,
  }
}];

const data = $input.first()?.json || {};
const generatedAt = new Date().toISOString();
const rewrittenTopics = Array.isArray(data.rewritten_topics) ? data.rewritten_topics : [];

function statusValue() {
  if (data.status === 'error') return 'error';
  if (data.status === 'insufficient_data') return 'insufficient_data';
  return 'success';
}

const readyTopics = rewrittenTopics.filter((topic) => topic.ready_for_agent3);
const reviewTopics = rewrittenTopics.filter((topic) => topic.review_required);
const blockedTopics = rewrittenTopics.filter((topic) => topic.final_risk_level === 'blocked' || topic.ready_for_agent3 === false);

const disclaimer = '本工具仅用于内容风险筛查和谨慎改写，不构成医疗、法律或平台合规意见。最终发布前仍需人工审核。';

function topicList(topics) {
  if (!topics.length) return '- 无。';
  return topics.map((topic, index) => `- ${index + 1}. ${topic.compliant_title || topic.original_title}`).join('\n');
}

function detailList(topics) {
  if (!topics.length) return '- 无。';
  return topics.map((topic, index) => [
    `### ${index + 1}. ${topic.original_title}`,
    `- 原标题：${topic.original_title}`,
    `- 改写标题：${topic.compliant_title}`,
    `- 原 Hook：${topic.original_hook || '无'}`,
    `- 改写 Hook：${topic.compliant_hook}`,
    `- 安全核心表述：${topic.safe_core_claim}`,
    `- 原风险等级：${topic.risk_check?.risk_level || 'unknown'}`,
    `- 最终风险等级：${topic.final_risk_level}`,
    `- 标记词：${(topic.risk_check?.flagged_phrases || []).join(', ') || '无'}`,
    `- 修改/移除词：${(topic.removed_or_changed_phrases || []).join(', ') || '无'}`,
    `- 修改说明：${topic.rewrite_explanation}`,
    `- 是否可进入 Agent 3：${topic.ready_for_agent3 ? 'Yes' : 'No'}`,
    `- 是否需要人工复核：${topic.review_required ? 'Yes' : 'No'}`,
  ].join('\n')).join('\n\n');
}

const jsonResult = {
  workflow: 'AI Health OS',
  source_agent: 'agent_e',
  agent: 'agent_2',
  version: '1.1',
  status: statusValue(),
  generated_at: generatedAt,
  total_topics: rewrittenTopics.length,
  approved_topics: data.selected_topics || [],
  compliance_results: rewrittenTopics,
  handoff: {
    next_agent: 'agent_3',
    ready_count: readyTopics.length,
    blocked_count: blockedTopics.length,
    manual_review_count: reviewTopics.length,
  },
  disclaimer,
};

let reportMarkdown = '';
if (jsonResult.status === 'error') {
  reportMarkdown = [
    '# AI Health OS — Agent 2 健康合规改写报告',
    '',
    '## 一、本次处理结果',
    `- 状态：error`,
    `- 错误原因：${data.parse_error || '未知错误'}`,
    '',
    '## 六、下一步',
    '- 请回到 Agent E / Agent 1，复制完整 JSON 后重新提交。',
    '',
    '## 重要说明',
    disclaimer,
  ].join('\n');
} else if (jsonResult.status === 'insufficient_data') {
  reportMarkdown = [
    '# AI Health OS — Agent 2 健康合规改写报告',
    '',
    '## 一、本次处理结果',
    '- 状态：insufficient_data',
    `- 原因：${data.selection_note || '没有合格选题。'}`,
    '',
    '## 二、可进入 Agent 3 的选题',
    '- 无。',
    '',
    '## 三、需要人工复核的选题',
    '- 无。',
    '',
    '## 四、被拦截的高风险选题',
    '- 无。',
    '',
    '## 五、每个选题的修改说明',
    '- 无。',
    '',
    '## 六、下一步',
    '- 请在表单中填写人工确认的选题名称或编号，或确认 Agent 1 JSON 中存在 A/B 且 Yes 的选题。',
    '',
    '## 重要说明',
    disclaimer,
  ].join('\n');
} else {
  reportMarkdown = [
    '# AI Health OS — Agent 2 健康合规改写报告',
    '',
    '## 一、本次处理结果',
    `- 本次处理选题数：${jsonResult.total_topics}`,
    `- 可进入 Agent 3：${jsonResult.handoff.ready_count}`,
    `- 需要人工复核：${jsonResult.handoff.manual_review_count}`,
    `- 被拦截：${jsonResult.handoff.blocked_count}`,
    '',
    '## 二、可进入 Agent 3 的选题',
    topicList(readyTopics),
    '',
    '## 三、需要人工复核的选题',
    topicList(reviewTopics),
    '',
    '## 四、被拦截的高风险选题',
    topicList(blockedTopics),
    '',
    '## 五、每个选题的修改说明',
    detailList(rewrittenTopics),
    '',
    '## 六、下一步',
    '- 只把 ready_for_agent3 = Yes 的选题交给未来 Agent 3。',
    '- review_required = Yes 的选题必须先人工确认。',
    '- blocked 或涉及治疗、治愈、替代药物、保证结果的内容不要继续制作。',
    '',
    '## 重要说明',
